begin;
create table if not exists hq.legal_permits(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),permit_type text not null,name text not null,authority text,permit_number text,issued_on date,expires_on date,status text not null default 'active' check(status in('pending','active','renewal_due','expired','suspended','cancelled')),document_id uuid references hq.documents(id),owner_employee_id uuid references hq.employees(id),created_at timestamptz not null default now());
create table if not exists hq.legal_consultations(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),subject text not null,requester text,counsel text,summary text,status text not null default 'open' check(status in('open','in_review','answered','closed')),due_at timestamptz,owner_employee_id uuid references hq.employees(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists hq.legal_document_versions(id uuid primary key default gen_random_uuid(),document_id uuid not null references hq.documents(id) on delete cascade,version integer not null,storage_key text not null,mime_type text,change_summary text,created_by uuid references hq.employees(id),created_at timestamptz not null default now(),unique(document_id,version));
create table if not exists hq.legal_document_access_log(id uuid primary key default gen_random_uuid(),document_id uuid not null references hq.documents(id) on delete cascade,employee_id uuid not null references hq.employees(id),action text not null check(action in('view_metadata','open','download','version_view')),occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);
do $$ declare t text; begin foreach t in array array['legal_permits','legal_consultations','legal_document_versions','legal_document_access_log'] loop execute format('alter table hq.%I enable row level security',t); execute format('revoke all on hq.%I from public,anon,authenticated',t); execute format('grant all on hq.%I to service_role',t); end loop; end $$;
create index if not exists idx_hq_permits_expiry on hq.legal_permits(expires_on,status);create index if not exists idx_hq_legal_consultations_due on hq.legal_consultations(due_at,status);create index if not exists idx_hq_legal_document_access on hq.legal_document_access_log(document_id,occurred_at desc);
commit;
